#!/bin/bash
set -e
echo "=== HDAR Cross-Platform Continuation Proof ==="
echo "Host A: macOS ARM64 (founder laptop)"
echo "Host B: $(uname -a)"
echo

pip install cryptography -q 2>&1 | tail -1

mkdir -p /tmp/hdar-proof && cd /tmp/hdar-proof
echo "Extracting deploy package..."
echo "" | base64 -d | tar xz

echo "Verifying runner hash..."
RUNNER_SHA="$(python3 -c "import json; r=json.load(open('host_a_build_report.json')); print(r['transport_bundle']['sha256'])")"
ACTUAL_SHA="$(sha256sum run_on_host_b.py | awk '{print $1}')"
echo "  Expected: $RUNNER_SHA"
echo "  Actual:   $ACTUAL_SHA"
if [ "$RUNNER_SHA" != "$ACTUAL_SHA" ]; then
  echo "  MISMATCH! Aborting."
  exit 1
fi
echo "  MATCH"
echo

OWNER_KEY="$(cat owner_public_key.txt)"
HOST_A_PLATFORM="$(python3 -c "import json; print(json.load(open('host_a_build_report.json'))['host_a_platform'])")"

echo "=== HOST B EXECUTION ==="
python3 run_on_host_b.py   --out /tmp/hdar-output   --host-label "codespace-independent"   --host-a-report host_a_build_report.json   --verify-runner-hash "$RUNNER_SHA"   --owner-public-key "$OWNER_KEY"   --operator-identity "github-codespace"   --network-source "codespace-api" > /tmp/host_b_stdout.json 2>/tmp/host_b_stderr.txt
EXIT_CODE=$?
echo "Exit code: $EXIT_CODE"
if [ $EXIT_CODE -ne 0 ]; then
  echo "STDERR:"
  cat /tmp/host_b_stderr.txt
  exit 1
fi

echo
echo "=== HOST B REPORT SUMMARY ==="
python3 -c "
import json
r = json.load(open('/tmp/host_b_stdout.json'))
print(f"Platform: {r['host_b_platform']}")
print(f"Restore exact: {r['restore']['exact']}")
tc = r.get('task_continuation', {})
print(f"Task: {tc.get('task', 'N/A')}")
print(f"Stages: {tc.get('stages_completed', 'N/A')}")
print(f"Output hash match: {tc.get('passed', 'N/A')}")
print(f"Owner sig verified: {r['input_capsule']['owner_signature_verified']['ok']}")
print(f"Host B sig: {r.get('host_b_signature', 'N/A')[:20]}...")
"

echo
echo "=== EXTRACTION FOR VERIFIER ==="
tar xzf transport_capsule_epoch_1_signed.tar.gz

echo
echo "=== THIRD-PARTY VERIFIER ==="
python3 third_party_verifier.py   --capsule-e1 capsule_epoch_1   --capsule-e2 /tmp/hdar-output/capsule_epoch_2   --host-b-report /tmp/hdar-output/host_b_report.json   --evidence-packet /tmp/hdar-output/host_b_evidence_packet.json   --owner-public-key "$OWNER_KEY"   --host-a-platform "$HOST_A_PLATFORM" 2>/dev/null

echo
echo "=== PROOF COMPLETE ==="
echo "Artifacts in /tmp/hdar-output/"
ls -la /tmp/hdar-output/
